/**
 * Signals in message HANDSHAKE.
 *
 * Startup init to check ID and FW for all units, inititate reset or reconfig if needed
 *
 * All signal values are as on the CAN bus.
 */
struct cmc_can_message_handshake_t {
    /**
     * Hardware major version
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t hw_version_major;

    /**
     * Hardware minor version
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t hw_version_minor;

    /**
     * Unique ID for the source unit
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t unit_id;

    /**
     * Unit type
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t unit_type;

    /**
     * Firmware major version, should listed for compability to ensure units can be combined
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t fw_version_major;

    /**
     * Firmware minor version, for info only
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t fw_version_minor;

    /**
     * All global configs across all units must be the same, datetime is when the config was created/updated, if not the same across units or if missing, the most recent updated config is to be used and passed over to units with old config
     *
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t gc_datetime;

    /**
     * All global configs across all units must be the same, this hash represent global config checksum
     *
     * Range: 0..4294967295 (0..4294967295 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t gc_hash;
};

/**
 * Signals in message HEARTBEAT.
 *
 * Poll on system frequently to identify missing units or mishaps
 *
 * All signal values are as on the CAN bus.
 */
struct cmc_can_message_heartbeat_t {
    /**
     * Unique ID for the source unit
     *
     * Range: 0..63 (0..63 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t unit_id;

    /**
     * Report system state for taking action if not OK
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t system_state;
};

/**
 * Signals in message FEATURE_HORN.
 *
 * Turn horn on/off
 *
 * All signal values are as on the CAN bus.
 */
struct cmc_can_message_feature_horn_t {
    /**
     * 0=off, 1=on
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t horn_on;
};

/**
 * Signals in message FEATURE_DIRECTION_INDICATOR.
 *
 * Turn direction indicators on/off, send also info for left, righ or both (hazard) and optionally if to be turned of only for front or rear, normally should be both. Separate for turning on indicator only, to be used for startup animation or check that dashboard indicator bulb works
 *
 * All signal values are as on the CAN bus.
 */
struct cmc_can_message_feature_direction_indicator_t {
    /**
     * 0=off, 1=on
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t turn_signal_on;

    /**
     * 0=left, 1=right, 2=both
     *
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t turn_signal_direction;

    /**
     * 0=front, 1=rear, 2=both
     *
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t turn_signal_position;

    /**
     * 0=normal operation, 1=only affect dashboard warning indicator
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dashboard_only;
};

